def comps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if (i,j) in seen or g[i][j]==0: continue
            c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
