def comps(g,val):
    seen=[[False]*len(g[0]) for _ in g]; res=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==val and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<len(g) and 0<=ny<len(g[0]) and not seen[nx][ny] and g[nx][ny]==val:
                                seen[nx][ny]=True; st.append((nx,ny))
                res.append(cells)
    return res
